#[cfg(test)]
mod exact_prefix_weakening_controls{
 use super::*;
 fn fixture()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){
  let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();
  for(id,x)in[(0,Expr::Sort(LevelId(0))),(1,Expr::Const{name:NameId(1),levels:vec![]}),(2,Expr::Pi{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Const{name:NameId(2),levels:vec![]}),(4,Expr::Const{name:NameId(3),levels:vec![]}),(5,Expr::BVar(0)),(6,Expr::Const{name:NameId(4),levels:vec![]})]{e.insert(ExprId(id),x).unwrap();}
  let mut tail=ExprId(4);for id in 8..24{e.insert(ExprId(id),Expr::App{fun:ExprId(3),arg:tail}).unwrap();tail=ExprId(id);}
  let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![],ExprId(2))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![],ExprId(1))).unwrap().extend(NameId(4),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap();(e,l,env)
 }
 fn dependent()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){
  let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();l.insert(LevelId(1),Level::Succ(LevelId(0))).unwrap();
  for(id,x)in[(0,Expr::Sort(LevelId(1))),(1,Expr::Const{name:NameId(1),levels:vec![]}),(2,Expr::Sort(LevelId(0))),(3,Expr::BVar(0)),(4,Expr::Const{name:NameId(2),levels:vec![]}),(5,Expr::App{fun:ExprId(4),arg:ExprId(3)}),(6,Expr::Pi{domain:ExprId(1),body:ExprId(2)}),(7,Expr::Pi{domain:ExprId(1),body:ExprId(5)}),(8,Expr::Const{name:NameId(3),levels:vec![]}),(9,Expr::App{fun:ExprId(8),arg:ExprId(3)})]{e.insert(ExprId(id),x).unwrap();}
  let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![],ExprId(6))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![],ExprId(7))).unwrap();(e,l,env)
 }
 #[test]fn completed_term_replays_only_under_exact_append(){
  let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=c.closure(ExprId(23),EnvFrame::empty());let g=vec![TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&g,&mut 4096,0);assert!(matches!(first,Some(TypeValue::Term(_))));let mut extended=g.clone();extended.push(g[0].clone());let mut work=1;assert_eq!(c.infer_exact_closure_in_context(&t,&extended,&mut work,0),first,"exact-prefix-paid-reuse");assert_eq!(work,0);
 }
 #[test]fn dependent_result_keeps_old_local_below_the_new_suffix_ordinal(){
  let _flags=crate::run_flags::enter();let(e,l,env)=dependent();let c=TypeChecker::new(&e,&l,&env);let t=c.closure(ExprId(9),EnvFrame::empty().extend_free(FreeId(0)));let g=vec![TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&g,&mut 4096,0);assert!(matches!(first,Some(TypeValue::Term(_))),"dependent cold fixture must synthesize source Term: {first:?}");let mut extended=g.clone();extended.push(g[0].clone());let warm=c.infer_exact_closure_in_context(&t,&extended,&mut 1,0);assert_eq!(warm,first,"prefix-dependent-paid-reuse");let Some(TypeValue::Term(ty))=warm else{panic!("completed dependent Term")};let v=c.machine().expose(ty,Transparency::Opaque,256);let Some(Value::Neutral(n))=v.proven_value()else{panic!("predicate type: {v:?}")};assert!(matches!(n.head,NeutralHead::Const{name:NameId(2),..}));assert_eq!(n.spine.len(),1);let arg=c.machine().expose(n.spine[0].clone(),Transparency::Opaque,256);assert!(matches!(arg.proven_value(),Some(Value::Neutral(Neutral{head:NeutralHead::Free(FreeId(0)),spine}))if spine.is_empty()),"new suffix FreeId(1) must not capture old local: {arg:?}");
 }
 #[test]fn contractions_changed_prefix_and_zero_work_cannot_replay(){
  let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=c.closure(ExprId(23),EnvFrame::empty());let g=vec![TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,0).is_some());assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());let changed=vec![TypeValue::Term(c.closure(ExprId(6),EnvFrame::empty())),g[0].clone()];assert!(c.infer_exact_closure_in_context(&t,&changed,&mut 1,0).is_none());let mut ext=g.clone();ext.push(g[0].clone());assert!(c.infer_exact_closure_in_context(&t,&ext,&mut 0,0).is_none());
 }
 #[test]fn borrowed_views_epoch_and_other_actual_subject_do_not_inherit_prefix_fact(){
  let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let mut c=TypeChecker::new(&e,&l,&env);let t=c.closure(ExprId(23),EnvFrame::empty());let g=vec![TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,0).is_some());let ext=vec![g[0].clone(),g[0].clone()];c.inherited_binding_lineage=Some(InheritedBindings{ledger:c.checked_binding_lineage.clone(),epoch:c.binding_revocation_epoch.clone(),captured_epoch:c.binding_revocation_epoch.get()});assert!(c.infer_exact_closure_in_context(&t,&ext,&mut 1,0).is_none());c.inherited_binding_lineage=None;c.binding_revocation_epoch.set(Some(1));assert!(c.infer_exact_closure_in_context(&t,&ext,&mut 1,0).is_none());c.binding_revocation_epoch.set(Some(0));let other=Closure::with_levels(t.expr,EnvFrame::empty().extend_free(FreeId(99)),t.levels.clone());assert!(c.infer_exact_closure_in_context(&other,&ext,&mut 1,0).is_none());
 }
 #[test]fn ordinal_source_match_does_not_supply_the_missing_origin_premise(){
  let _flags=crate::run_flags::enter();let(e,l,env)=dependent();let mut c=TypeChecker::new(&e,&l,&env);c.strict_origin_probe=true;let a=c.closure(ExprId(5),EnvFrame::empty().extend_free(FreeId(0)));let b=c.closure(ExprId(5),EnvFrame::empty().extend_free(FreeId(0)));assert_ne!(a.env.id(),b.env.id());assert!(c.relational_source_substitution(&a,&b,&mut 512),"ordinal source matcher sees the same FreeId(0)");let base=TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()));let old=vec![base.clone(),TypeValue::Term(a.clone())];let new=vec![base,TypeValue::Term(b)];let h=EnvFrame::empty().extend_free(FreeId(1));c.retain_checked_binding(&h,TypeValue::Term(a.clone()),&old);assert_eq!(c.checked_type_of_bound_source(&h,0,&old),Some(TypeValue::Term(a)));assert!(c.checked_type_of_bound_source(&h,0,&new).is_none(),"origin protection must not be replaced by ordinal source matching");
 }
}
